INSERT INTO `clearance_document` VALUES (1,'Passenger manifest complete','All checked-in passengers are listed with full name, age, sex and nationality',1,'manifest',1,1),(2,'Passenger count within capacity','Checked-in + boarded passengers do not exceed the certified passenger capacity',1,'pax_capacity',2,1),(3,'Total load within allowable kg','Passengers, baggage, cargo and vehicles do not exceed the vessel\'s max load (kg)',1,'load_capacity',3,1),(4,'Loads sorted into zones','Every vehicle and cargo item has an assigned zone (A1/A2/B1...) and no zone is over its limit',1,'zones',4,1),(5,'Manifest locked','Check-in is closed and the manifest is locked',1,'locked',5,1),(6,'Vessel not under maintenance','Vessel is operational for this voyage date',1,'maintenance',6,1),(7,'Crew list presented','Crew count entered on the manifest; master and crew list matches the Minimum Safe Manning Certificate',1,'crew',7,1),(8,'Life-saving appliances checked','Life jackets, life rafts and buoys are complete and accessible',1,NULL,8,1),(9,'Weather / sea condition acceptable','No gale warning or tropical cyclone signal for the route',1,NULL,9,1),(10,'Hazardous cargo declared','Hazardous cargo (if any) is declared and stowed in an allowed zone',1,'hazard',10,1);
/*!40000 ALTER TABLE `clearance_document` ENABLE KEYS */;
