DROP TABLE IF EXISTS `departure_clearance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `departure_clearance` (
  `clearance_id` int(11) NOT NULL AUTO_INCREMENT,
  `voyage_id` int(11) NOT NULL,
  `cert_no` varchar(30) NOT NULL,
  `is_cleared` tinyint(1) NOT NULL DEFAULT 1,
  `total_pax` int(11) NOT NULL DEFAULT 0,
  `total_crew` int(11) NOT NULL DEFAULT 0,
  `total_vehicles` int(11) NOT NULL DEFAULT 0,
  `total_load_kg` decimal(12,2) NOT NULL DEFAULT 0.00,
  `checklist` longtext DEFAULT NULL COMMENT 'JSON snapshot of the checklist',
  `valid_until` datetime NOT NULL COMMENT 'certificate validity (departure + grace)',
  `issued_by` int(11) DEFAULT NULL,
  `issued_at` datetime DEFAULT current_timestamp(),
  `notes` text DEFAULT NULL,
  PRIMARY KEY (`clearance_id`),
  UNIQUE KEY `cert_no` (`cert_no`),
  KEY `voyage_id` (`voyage_id`),
  KEY `clr_user_fk` (`issued_by`),
  CONSTRAINT `clr_user_fk` FOREIGN KEY (`issued_by`) REFERENCES `user` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `clr_voyage_fk` FOREIGN KEY (`voyage_id`) REFERENCES `voyage` (`voyage_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `departure_clearance` WRITE;
/*!40000 ALTER TABLE `departure_clearance` DISABLE KEYS */;
INSERT INTO `departure_clearance` VALUES (1,55,'CERT-2026-00001',1,0,13,0,0.00,'[{\"doc_id\":1,\"label\":\"Passenger manifest complete\",\"auto\":\"manifest\",\"required\":1,\"ok\":true,\"detail\":\"0 passenger(s) on manifest, all complete\"},{\"doc_id\":2,\"label\":\"Passenger count within capacity\",\"auto\":\"pax_capacity\",\"required\":1,\"ok\":true,\"detail\":\"0 \\/ 374 passengers (0%)\"},{\"doc_id\":3,\"label\":\"Total load within allowable kg\",\"auto\":\"load_capacity\",\"required\":1,\"ok\":true,\"detail\":\"0 kg \\/ 15,000 kg (0%)\"},{\"doc_id\":4,\"label\":\"Loads sorted into zones\",\"auto\":\"zones\",\"required\":1,\"ok\":true,\"detail\":\"No vehicles or cargo on this voyage\"},{\"doc_id\":5,\"label\":\"Manifest locked\",\"auto\":\"locked\",\"required\":1,\"ok\":true,\"detail\":\"Manifest status: Locked\"},{\"doc_id\":6,\"label\":\"Vessel not under maintenance\",\"auto\":\"maintenance\",\"required\":1,\"ok\":true,\"detail\":\"Vessel operational\"},{\"doc_id\":7,\"label\":\"Crew list presented\",\"auto\":\"crew\",\"required\":1,\"ok\":true,\"detail\":\"13 crew on the crew list\"},{\"doc_id\":8,\"label\":\"Life-saving appliances checked\",\"auto\":null,\"required\":1,\"ok\":true,\"detail\":\"\"},{\"doc_id\":9,\"label\":\"Weather \\/ sea condition acceptable\",\"auto\":null,\"required\":1,\"ok\":true,\"detail\":\"\"},{\"doc_id\":10,\"label\":\"Hazardous cargo declared\",\"auto\":\"hazard\",\"required\":1,\"ok\":true,\"detail\":\"No hazardous cargo\"}]','2026-10-11 10:00:00',6,'2026-10-09 09:19:44',NULL);
